import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:window_manager/window_manager.dart';
import 'core/app_state.dart';import 'screens/app_shell.dart';import 'services/api_service.dart';import 'services/history_service.dart';import 'services/local_engine_service.dart';import 'services/settings_service.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await windowManager.ensureInitialized();const options=WindowOptions(size:Size(1220,780),minimumSize:Size(900,620),center:true,title:'XAI-Compress Desktop');windowManager.waitUntilReadyToShow(options,()async{await windowManager.show();await windowManager.focus();});runApp(ChangeNotifierProvider(create:(_)=>AppState(engine:LocalEngineService(),api:ApiService(),history:HistoryService(),settings:SettingsService())..initialize(),child:const DesktopApp()));}
class DesktopApp extends StatelessWidget{const DesktopApp({super.key});@override Widget build(BuildContext c)=>Consumer<AppState>(builder:(c,s,_)=>MaterialApp(debugShowCheckedModeBanner:false,title:'XAI-Compress',themeMode:s.darkMode?ThemeMode.dark:ThemeMode.light,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff4054d6)),useMaterial3:true),darkTheme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff8c9bff),brightness:Brightness.dark),useMaterial3:true),home:s.loading?const Scaffold(body:Center(child:CircularProgressIndicator())):const AppShell()));}
